/* Lobby and private-room transport. No simulated people or matchmaking. */
const PROFILE_KEY='grail-profile-v04';
let profile={character:'artoria',nickname:'마스터',goals:{artoria:['bastard_sword'],yukina:['long_spear'],amuro:['rail_rifle'],link:['hades_edge']}};
try{const saved=JSON.parse(localStorage.getItem(PROFILE_KEY));if(saved&&CHARACTERS[saved.character])profile={...profile,...saved};}catch{}
profile.goals={artoria:['bastard_sword'],yukina:['long_spear'],amuro:['rail_rifle'],link:['hades_edge'],...profile.goals};
function saveProfile(){try{localStorage.setItem(PROFILE_KEY,JSON.stringify(profile));}catch{}}
let front='home',serverAvailable=false,roomKey=sessionStorage.getItem('grail-room-key')||'',roomView=null,polling=false,networkError='',lastBattleSignature='',resultShown=false;
window.frontScreen=true;window.roomConnected=false;
const original={render,updateHud,attack,defense,ownMaxHp,ownMaxSta,nextClosure,closedRegions,closurePair,elapsed};
elapsed=()=>state?.finished?state.elapsedSeconds:original.elapsed();
const onlineEffects=id=>Object.values(state.equipment).flatMap(x=>ITEMS[x]?.effects||[]).filter(x=>x.id===id).reduce((s,e)=>s+e.value,0);
ownMaxHp=()=>original.ownMaxHp()+onlineEffects('max_hp');
closedRegions=()=>window.roomConnected||(!window.frontScreen&&window.practiceCoreActive)?state.closed:original.closedRegions();
closurePair=()=>window.roomConnected||(!window.frontScreen&&window.practiceCoreActive)?(state.upcoming?.ids||[]):original.closurePair();
nextClosure=()=>window.roomConnected||(!window.frontScreen&&window.practiceCoreActive)?state.upcoming?.t:original.nextClosure();
function button(action,text,cls=''){return `<button class="lobby-btn ${cls}" data-front="${action}">${text}</button>`;}
function lobbyTop(){return `<header class="lobby-top"><a href="#" data-front="home" class="lobby-brand">${icon('grail')}<span>성배전쟁<small>HOLY GRAIL WAR</small></span></a><span class="build-tag">PLAYABLE ALPHA · 13.0</span><span class="connection-badge ${serverAvailable?'connected':''}"><i></i>${serverAvailable?'게임 서버 연결됨':'브라우저 체험'}</span>${button('settings',icon('settings')+'<span>설정</span>')}</header>`;}
function nav(){return `<nav class="lobby-nav" aria-label="로비 메뉴">${[['home','grail','로비'],['servants','people','서번트'],['prepare','target','준비 설정'],['encyclopedia','book','아이템 도감'],['rules','paper','게임 규칙']].map(([a,i,t])=>`<button data-front="${a}" class="${front===a?'active':''}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`;}
function footer(){return `<footer class="lobby-footer"><span>서번트 4종 · 지역 ${DATA.regions.length}곳 · 아이템 ${DATA.items.length}종</span><span>비공개 방 · 캐릭터 중복 허용</span></footer>`;}
function frontRender(){delete $('#modal').dataset.zoneDanger;window.frontScreen=true;document.body.classList.add('in-lobby');const c=CHARACTERS[profile.character];
 let body='';if(front==='home')body=`<section class="home-hero"><div class="hero-copy"><span class="eyebrow">A CONTRACT BEFORE THE WAR</span><h1>살아남아,<br><em>성배에 닿아라.</em></h1><p>탐색하고, 만들어라.<br>마지막 계약이 남을 때까지.</p><div class="hero-character"><span>${c.class}</span><strong>${c.full}</strong>${button('servants','서번트 변경 ↗')}</div></div><div class="hero-art">${characterArtwork(profile.character,'selection')}<span class="hero-art-caption">SERVANT RECORD / ${c.class}</span></div><aside class="home-launch"><div class="eyebrow">PRIVATE BATTLE</div><h2>출전 준비</h2><p>친구와 방 코드를 공유하고<br>같은 전장에서 만나요.</p><div class="launch-rules"><span>정규 개인전 <b>4인</b></span><span>현재 계약 <b>${c.name}</b></span><span>령주 <b>3획</b></span></div>${button('battle','대전 시작 '+icon('arrow'),'primary')}${button('practice','혼자 UI 연습')}<small>${serverAvailable?'2~3인 개발 검증 대전도 시작할 수 있어요.':'실제 대전은 로컬 게임 서버에서 이용할 수 있어요.'}</small></aside></section><section class="home-bottom"><div><span>01 / PREPARE</span><strong>나만의 제작 목표</strong><p>즐겨찾기에서 다음 장비를 준비하세요.</p>${button('prepare','준비 설정 ↗')}</div><div><span>02 / SURVIVE</span><strong>정보가 곧 생존</strong><p>아이템의 재료와 발견 지역을 확인하세요.</p>${button('encyclopedia','도감 열기 ↗')}</div><div><span>03 / LAST CONTRACT</span><strong>최후의 마스터</strong><p>폐쇄되는 지역을 피해 마지막까지 버티세요.</p>${button('rules','경기 규칙 ↗')}</div></section>`;
 else if(front==='servants')body=`<section class="lobby-page"><div class="page-heading"><div><span class="eyebrow">SERVANT ARCHIVE</span><h1>계약할 서번트</h1><p>패시브와 보구를 확인하고 전투 방식을 선택하세요.</p></div><span class="muted">선택 가능 4 / 추가 캐릭터 설계 중</span></div><div class="servant-layout"><div class="servant-cards">${Object.entries(CHARACTERS).map(([id,c])=>`<button class="servant-pick ${profile.character===id?'selected':''}" data-front="pick" data-id="${id}"><span class="pick-status">${profile.character===id?'계약 중':'선택하기'}</span>${characterArtwork(id,'selection')}<span class="caps">${c.class}</span><strong>${c.full}</strong><span>${c.passive} / ${c.np}</span></button>`).join('')}</div><article class="servant-detail"><span class="eyebrow">${c.class} / CONTRACT INFORMATION</span><h2>${c.full}</h2><div class="lobby-stats">${[['HP',c.maxHp,c.hpGrowth],['STA',c.maxSta,c.staGrowth],['공격',c.attack,c.atkGrowth],['방어',c.defense,c.defGrowth]].map(([n,v,g])=>`<div><span>${n}</span><strong>${v}</strong><small>레벨당 +${g}</small></div>`).join('')}</div><p class="detail-mastery">주력 숙련도 · ${c.weaponType==='blade'?'베기':c.weaponType==='gun'?'총':'찌르기'} D+</p><h3><span>PASSIVE</span> ${c.passive}</h3><p>${c.passiveText}${profile.character==='artoria'?' · 마법 상태 부여 확률 20% 감소':profile.character==='yukina'?' · 회피 후 재사용 30초 · 동물·보구 제외':''}</p><h3><span>NOBLE PHANTASM</span> ${c.np}</h3><p>${c.npText}</p><p class="detail-cooldown">${c.cast?'시전 '+c.cast+'초':'즉시 발동'} · STA ${c.cost} · 재사용 ${c.cd}초</p>${button('home','이 서번트로 로비 복귀','primary')}</article></div></section>`;
 else if(front==='prepare')body=`<section class="lobby-page"><div class="page-heading"><div><span class="eyebrow">BATTLE PLANNING</span><h1>준비 설정</h1><p>목표 아이템을 저장해 경기 중 빠르게 확인하세요. 장비가 지급되는 기능은 아닙니다.</p></div></div><div class="prepare-tabs">${Object.entries(CHARACTERS).map(([id,c])=>`<button data-front="prep-character" data-id="${id}" class="${profile.character===id?'active':''}">${c.name}</button>`).join('')}</div><div class="goal-bookmarks">${(profile.goals[profile.character]||[]).map(id=>`<button data-front="remove-goal" data-id="${id}"><span class="item-emblem rarity-${ITEMS[id].rarity}">${icon(itemIcon(ITEMS[id]))}</span><strong>${esc(ITEMS[id].name)}</strong><small>${esc(itemStat(ITEMS[id]))}</small><span class="remove-bookmark">× 제거</span></button>`).join('')}${button('bookmark-add','+<span>목표 추가</span>','bookmark-add')}</div><div class="lobby-note">즐겨찾기는 최대 8개까지 저장합니다. 첫 번째 목표를 경기 시작 시 표시하며, 도감에서 언제든 바꿀 수 있어요.</div>${button('home','로비로 돌아가기')}</section>`;
 else if(front==='battle')body=`<section class="lobby-page"><div class="page-heading"><div><span class="eyebrow">ENTER THE HOLY GRAIL WAR</span><h1>비공개 대전</h1><p>방을 만들거나 친구가 공유한 6자리 코드를 입력하세요.</p></div></div><div class="entry-grid"><article><span class="eyebrow">CREATE ROOM</span><h2>새로운 전장</h2><p>방장이 되어 친구들을 초대하세요.</p><label>마스터 이름<input id="master-name" maxlength="16" value="${esc(profile.nickname)}" autocomplete="off"></label><p class="gold">${c.full} · ${c.class}</p>${button('create','방 만들기','primary')}</article><article><span class="eyebrow">JOIN ROOM</span><h2>계약에 합류</h2><p>같은 게임 서버의 방 코드가 필요해요.</p><label>방 코드<input id="room-code" inputmode="numeric" maxlength="6" placeholder="6자리 숫자" autocomplete="off"></label>${button('join','방 참가하기')}</article></div>${!serverAvailable?'<div class="lobby-note">현재 페이지는 로비/UI 체험용 공개본입니다. 실제 방 대전은 프로젝트 폴더에서 게임 서버를 실행한 뒤 http://127.0.0.1:4173 에서 이용하세요. 자동 매칭과 AI 충원은 제공하지 않습니다.</div>':''}<div class="lobby-note">정규 4인 개인전 · 개발 검증은 2~3인 가능 · 모든 참가자 준비 후 방장 시작</div></section>`;
 else if(front==='room')body=roomMarkup();else if(front==='deployment')body=deploymentMarkup();
 $('#app').innerHTML=`<div class="lobby-shell">${lobbyTop()}<div class="lobby-layout">${nav()}<main class="lobby-content">${networkError?`<div class="network-alert" role="alert">${esc(networkError)}</div>`:''}${body}</main></div>${footer()}</div>`;
}
function roomMarkup(){if(!roomView)return '';return `<section class="lobby-page"><div class="page-heading"><div><span class="eyebrow">CONTRACT ROOM</span><h1>참가자를 기다리는 중</h1><p>방 코드 <strong class="room-code">${roomView.code}</strong> · ${roomView.roster.length} / 4명</p></div>${button('leave','방 나가기')}</div><div class="room-cards">${Array.from({length:4},(_,i)=>{const p=roomView.roster[i];return p?`<article class="room-card ${p.ready?'ready':''}"><span class="room-player">${esc(p.nickname)} ${p.isSelf?'· 나':''}${p.isHost?' · 방장':''}</span>${characterArtwork(p.character,'selection')}<span class="caps">${CHARACTERS[p.character].class}</span><h3>${CHARACTERS[p.character].name}</h3><strong class="room-ready">${p.ready?'준비 완료':'준비 중'}</strong></article>`:`<div class="room-card vacant">${icon('people')}<span>계약을 기다리는 중</span></div>`;}).join('')}</div><div class="room-actions">${button('ready',roomView.roster.find(p=>p.isSelf)?.ready?'준비 취소':'준비 완료','primary')}${roomView.isHost?button('start','경기 시작 '+icon('arrow')):''}</div><p class="lobby-note">${roomView.roster.length===4?'4인 개인전':'2~3인 개발 검증 대전'} · 방장은 모두 준비한 뒤 시작할 수 있어요. 시작하면 서번트를 변경할 수 없습니다.</p></section>`;}
async function api(path,body){const res=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{...(body?{'Content-Type':'application/json'}:{}),...(roomKey?{Authorization:'Bearer '+roomKey}:{})},body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(5000)});const json=await res.json();if(!res.ok){const error=Error(json.error||'요청에 실패했습니다.');error.status=res.status;throw error;}return json;}
async function enterRoom(kind){if(!serverAvailable){toast('실제 대전은 로컬 게임 서버에서 이용해 주세요.');return;}profile.nickname=$('#master-name').value.trim().slice(0,16)||'마스터';saveProfile();const code=$('#room-code')?.value;const data=await api(kind,{character:profile.character,nickname:profile.nickname,code});roomKey=data.key;sessionStorage.setItem('grail-room-key',roomKey);resultShown=false;await syncRoom();}
async function send(action,extra={}){try{roomView=await api('action',{action,requestId:crypto.randomUUID(),...extra});networkError='';applyRoom();}catch(e){toast(e.message);}}
async function syncRoom(){if(!roomKey||polling)return;polling=true;const key=roomKey;try{const data=await api('state');if(key!==roomKey)return;networkError='';roomView=data;applyRoom();}catch(e){if(key!==roomKey)return;if(e.status===400){roomKey='';sessionStorage.removeItem('grail-room-key');window.roomConnected=false;window.frontScreen=true;state=null;front='home';networkError='이전 방이 종료되었습니다. 새 방을 만들거나 참가해 주세요.';frontRender();return;}networkError='서버 연결을 확인하고 있습니다. 60초 이상 끊기면 대전에서 탈락합니다.';if(window.roomConnected)toast(networkError);else if(front==='room')frontRender();}finally{polling=false;}}
function applyRoom(){if(!roomView||!roomKey)return;if(roomView.phase==='waiting'){const signature=JSON.stringify(roomView.roster);if(front!=='room'||signature!==lastBattleSignature){front='room';lastBattleSignature=signature;frontRender();}return;}if(roomView.phase==='selecting'){window.roomConnected=false;const sig=JSON.stringify([roomView.ownRegion,roomView.selectedCount]);if(front!=='deployment'||lastBattleSignature!==sig){front='deployment';lastBattleSignature=sig;frontRender();}return;}window.roomConnected=true;window.frontScreen=false;document.body.classList.remove('in-lobby');const incoming=structuredClone(roomView.state),offset=clock()-roomView.serverNow;
 for(const k of ['started','sealUntil','hpFoodUntil','staFoodUntil','npUntil','attackUntil','moveUntil','evadeUntil','encounterUntil','markUntil','stanceUntil','predictionUntil'])incoming[k]=incoming[k]?incoming[k]+offset:0;if(incoming.busy){incoming.busy.start+=offset;incoming.busy.end+=offset;}if(incoming.enemy?.markUntil)incoming.enemy.markUntil+=offset;for(const s of [...(incoming.statuses||[]),...(incoming.enemy?.statuses||[])])s.until+=offset;
 const old=state;state={target:profile.goals[incoming.character]?.[0]||CHARACTERS[incoming.character].goal,filter:'all',query:'',selected:null,guideHistory:[],guideId:null,mapFocus:null,warningDemo:false,...old,...incoming};
 const signature=JSON.stringify([state.character,state.region,state.equipment,state.dead]);if(!$('#stage')||signature!==lastBattleSignature){const entering=!$('#stage');lastBattleSignature=signature;render();if(entering)window.scrollTo(0,0);}else{renderStage();const bagSig=JSON.stringify(state.bag);if($('#panel').dataset.bag!==bagSig){renderPanel();$('#panel').dataset.bag=bagSig;}renderLogs();updateHud();}
 if(roomView.phase==='finished'&&resultShown!=='finished'){resultShown='finished';showResults();}else if(state.dead&&!resultShown){resultShown='eliminated';showResults();}}
render=()=>{original.render();if(!window.roomConnected){const b=$('[data-action="character"]');if(b){b.dataset.front='practice-exit';b.removeAttribute('data-action');b.innerHTML='로비로';}return;}$('.match-label').innerHTML='비공개 생존전 <span class="muted">/</span> '+roomView.roster.length+'인';$('.subbar-right').innerHTML='<span>방 '+roomView.code+'</span><span class="demo-chip">SERVER ALPHA 13.0</span>';const change=$('[data-action="character"]');change.innerHTML=icon('arrow')+'<span class="button-label">로비로</span>';change.dataset.front='exit-battle';change.removeAttribute('data-action');$('.scene-menu').remove();$('.self-sub').textContent=CHARACTERS[state.character].class+' · '+(state.nickname||profile.nickname);$('.footer').innerHTML='<span>비공개 대전 · 게임 서버 판정 · 캐릭터 이미지 미사용</span><span>GRAIL WAR / ALPHA 13.0</span>';updateHud();};
updateHud=()=>{original.updateHud();if(window.roomConnected&&state.finished&&$('#action-group'))$('#action-group').innerHTML=button('results','경기 결과 보기','primary');if(window.roomConnected&&$('#level-value'))$('#level-value').textContent=state.level;if(window.roomConnected&&$('#alive-count'))$('#alive-count').innerHTML=state.alive+'<span class="muted"> / '+roomView.roster.length+'</span>';};
survivorsDialog=()=>{if(!window.roomConnected)return showModal('생존자 목록','<p>UI 연습에서는 참가자가 연결되어 있지 않습니다.</p>');showModal('참가자',`<div class="survivor-list">${roomView.roster.map(p=>`<div><span>${esc(p.nickname)}${p.isSelf?' · 나':''}</span><span>${CHARACTERS[p.character].name} · ${p.dead?'탈락':'생존'}</span></div>`).join('')}</div><p>상대 위치·가방·보구 대기시간은 공개하지 않습니다.</p>`);};
helpDialog=()=>showModal('조작 안내',`<p>탐색 R · 지도 E · 일반 공격 A · 보구 Q<br>휴식/도주 S · 장비 C · 도감 F · 바닥 물품 M · 령주 X<br>재장전 T · 빠른 HP/STA 회복 1/2 · 생존자 Tab · 닫기/행동 취소 Esc<br>태세는 상태창 오른쪽 버튼으로 전환 · 상태 아이콘 클릭: 효과 설명</p><p>알트리아는 탐색 화면에서 A로 지역 보구를 사용할 수 있습니다. 가방 아이템 위에 커서를 두고 V를 누르면 1개를 버립니다. 아이템 상세에서는 R 사용/장착, F 제작 가이드, V 버리기. 제작 가이드에서는 Space 제작입니다.</p><p>창을 열어도 대전 시간은 흐릅니다. 로컬 방 대전의 위치·HP·재료·시간·판정은 게임 서버가 결정합니다. 혼자 연습도 같은 게임 규칙을 사용하며 대전 기록으로 저장되지 않습니다. 서번트 조우 예시는 상황 테스트에서 직접 생성합니다.</p>`);
function showResults(){const result=roomView.result;showModal(result?.draw?'무승부':result?.won?'성배에 도달했습니다':'계약이 종료되었습니다',`<div class="result-summary">${icon('grail')}<h2>${result?.won?'최후의 생존자':result?.draw?'마지막 계약의 끝':'다음 전장을 준비하세요'}</h2><p>플레이 시간 ${timeString(elapsed())} · 내 처치 ${state.kills} · Lv.${state.level}</p></div><div class="survivor-list">${roomView.roster.map(p=>`<div><span>${esc(p.nickname)} · ${CHARACTERS[p.character].name}</span><span>처치 ${p.kills} · ${p.dead?'탈락':'생존'}</span></div>`).join('')}</div><div class="modal-actions">${button('leave','로비로 돌아가기','primary')}</div>`,'results');}
async function leaveRoom(){if(roomKey){try{await api('action',{action:'leave',requestId:crypto.randomUUID()});}catch{}}roomKey='';sessionStorage.removeItem('grail-room-key');roomView=null;window.roomConnected=false;window.frontScreen=true;sequence++;state=null;closeModal();front='home';lastBattleSignature='';frontRender();}
function frontDialog(action){if(action==='rules')showModal('성배전쟁 · 경기 규칙',`<p>4인 개인전 · 마지막 생존자 1명이 승리합니다. 캐릭터 중복 선택이 가능합니다.</p><p>탐색 1.5초 / STA 3 · 이동 STA 5 / 대기 3초<br>가방 6칸과 별도 장비 6칸 · 제작 1초<br>HP·STA 회복품은 각각 5초 대기 · 령주 3획</p><p>3·5·7·9분에 지역이 폐쇄됩니다. 30초 전에 예고하며 폐쇄 지역에 남으면 탈락합니다. 11분부터 HP 회복이 막히고 과부하 피해가 시작됩니다.</p><p>태세: 보통 발견70% / 공격90% / 은신50%·들킴 가중치80%. 전환 대기2초이며 ATK/DEF는 바꾸지 않습니다.</p><p>상태 효과는 내 상태창 오른쪽에 표시됩니다. 기절/속박 연속 제어는 최대3초, 종료 후2초 면역. 출혈/화상은 최대3중첩, 보호막은 최대HP30% 한도입니다. 가드는 미채택입니다.</p><p>숙련도 성장·시체 탐색과 선택 회수·같은 시각 피해 묶음·결과 기록을 적용합니다. 베기·찌르기·총 전투를 지원합니다. 총은 탄약이 필요하고 T키로 1.5초 재장전합니다. 다른 무기 계열과 해킹은 보류 항목입니다. 실제 사람끼리 대전하려면 로컬 서버에 접속해야 합니다.</p>`);else if(action==='settings')showModal('마스터 설정',`<label class="front-label">마스터 이름<input id="profile-name" maxlength="16" value="${esc(profile.nickname)}"></label><div class="modal-actions">${button('save-name','저장','primary')}</div><p>이름과 제작 목표는 이 브라우저에 저장됩니다.</p>`);else if(action==='bookmark-add'){showModal('목표 아이템 추가',`<label class="front-label">아이템 이름<input id="bookmark-search" type="search" placeholder="이름에 포함된 글자로 검색"></label><div id="bookmark-results" class="bookmark-results"></div>`);bookmarkResults('');}}
function bookmarkResults(q){const found=DATA.items.filter(i=>normalizeSearch(i.name).includes(normalizeSearch(q)));$('#bookmark-results').innerHTML=found.map(i=>`<button data-front="add-goal" data-id="${i.id}">${icon(itemIcon(i))}<span>${esc(i.name)}</span><small>${esc(itemStat(i))}</small></button>`).join('')||'<p>일치하는 아이템이 없습니다.</p>';}
document.addEventListener('input',e=>{if(e.target.id==='bookmark-search')bookmarkResults(e.target.value);});
document.addEventListener('keydown',e=>{if(window.frontScreen){if(e.key==='Escape'&&$('#modal').open)closeModal();e.stopImmediatePropagation();}},true);
document.addEventListener('click',async e=>{const btn=e.target.closest('[data-front]');if(btn){e.preventDefault();e.stopImmediatePropagation();const a=btn.dataset.front,id=btn.dataset.id;try{if(['home','servants','prepare','battle'].includes(a)){if(roomKey){toast('먼저 현재 방에서 나와 주세요.');return;}front=a;frontRender();}else if(a==='pick'||a==='prep-character'){profile.character=id;saveProfile();frontRender();}else if(a==='practice'){networkError='';deploySelected=null;front='deployment';frontRender();}else if(a==='practice-exit'){closeModal();sequence++;state=null;front='home';frontRender();}else if(a==='encyclopedia'){if(!state){state={bag:[],equipment:{},filter:'all',query:'',guideHistory:[],level:1,character:profile.character};}catalogDialog();}else if(a==='create'||a==='join')await enterRoom(a);else if(a==='deploy-confirm'){if(!deploySelected||DATA.regions.find(r=>r.id===deploySelected)?.restricted){toast('열린 지역을 선택해 주세요.');return;}if(roomKey)await send('start-region',{id:deploySelected});else{const id=deploySelected;window.frontScreen=false;document.body.classList.remove('in-lobby');start(profile.character);state.region=id;state.started=clock();state.logs=[];log(region().name+'에서 탐색을 시작합니다.');render();window.scrollTo(0,0);}}else if(a==='ready'||a==='start')await send(a);else if(a==='leave')await leaveRoom();else if(a==='exit-battle'){if(roomView.phase==='finished'||state.dead)await leaveRoom();else showModal('전장을 떠나시겠습니까?',`<p>진행 중 나가면 기권으로 처리됩니다.</p><div class="modal-actions">${button('leave','기권하고 로비로')}${button('stay','계속 플레이','primary')}</div>`);}else if(a==='stay')closeModal();else if(a==='results')showResults();else if(a==='save-name'){profile.nickname=$('#profile-name').value.trim().slice(0,16)||'마스터';saveProfile();closeModal();frontRender();}else if(a==='add-goal'){const goals=profile.goals[profile.character]??=[];if(goals.includes(id))toast('이미 등록한 목표입니다.');else if(goals.length>=8)toast('목표는 최대 8개까지 등록할 수 있어요.');else{goals.push(id);saveProfile();closeModal();frontRender();}}else if(a==='remove-goal'){profile.goals[profile.character]=profile.goals[profile.character].filter(x=>x!==id);saveProfile();frontRender();}else frontDialog(a);}catch(error){toast(error.message);}return;}
 if(window.frontScreen){const action=e.target.closest('[data-action]')?.dataset.action;if(action&&['set-target','craft','travel','equip','use-item'].includes(action)){e.stopImmediatePropagation();toast('준비 설정에서 목표를 저장하거나 대전에 입장해 주세요.');}return;}
 if(!window.roomConnected)return;const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,slot=Number(b.dataset.slot),id=b.dataset.id;const commands={search:()=>send('search'),attack:()=>send('attack'),np:()=>send('np'),cancel:()=>send('cancel'),travel:()=>send('travel',{id}),'seal-travel':()=>send('travel',{id,seal:true}),'seal-heal':()=>send('seal-heal'),'start-rest':()=>send('rest',{resource:b.dataset.resource==='stamina'?'sta':b.dataset.resource}),'use-item':()=>send('food',{slot}),equip:()=>chooseEquip(slot),craft:()=>chooseCraft(id),discard:()=>send('discard',{slot}),pickup:()=>send('pickup',{slot}),quick:()=>{const resource=b.dataset.resource;const index=state.bag.findIndex(x=>x&&ITEMS[x.id].restoreResource===resource);if(index>=0)return send('food',{slot:index});},reset:()=>showResults()};if(commands[a]){e.stopImmediatePropagation();closeModal();await commands[a]();}},true);
document.addEventListener('keydown',e=>{if(!window.roomConnected||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.repeat||e.ctrlKey||e.altKey||e.metaKey)return;const key=e.key.toLowerCase();if($('#modal').open){if(modalType==='item'&&['r','v'].includes(key)){e.preventDefault();e.stopImmediatePropagation();const n=state.selected?.index,i=ITEMS[state.bag[n]?.id];if(i&&state.bag[n].id===state.selected.id){closeModal();if(key==='v')send('discard',{slot:n});else if(i.kind==='food')send('food',{slot:n});else chooseEquip(n);}}else if(modalType==='guide'&&key===' '){e.preventDefault();e.stopImmediatePropagation();chooseCraft(state.guideId);}return;}const actions={escape:()=>send('cancel'),r:()=>send('search'),a:()=>send(currentEncounter()?'attack':'np'),q:()=>send('np'),'1':()=>{const slot=state.bag.findIndex(x=>x&&ITEMS[x.id].restoreResource==='hp');if(slot>=0)send('food',{slot});},'2':()=>{const slot=state.bag.findIndex(x=>x&&ITEMS[x.id].restoreResource==='stamina');if(slot>=0)send('food',{slot});}};if(key==='s'&&state.rest)actions.s=()=>send('rest',{resource:state.rest});if(actions[key]){e.preventDefault();e.stopImmediatePropagation();actions[key]();}},true);
frontRender();
fetch('/api/health',{signal:AbortSignal.timeout(2500)}).then(r=>r.json()).then(j=>{serverAvailable=j.ok===true;if(serverAvailable&&roomKey)syncRoom();else frontRender();}).catch(()=>{serverAvailable=false;frontRender();});
setInterval(()=>{if(roomKey)syncRoom();},400);
